import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { AiAgentService } from '../../services/ai-agent.service';

@Component({
  standalone: true,
  selector: 'app-ai-agent',
  imports: [CommonModule, FormsModule],
  templateUrl: './ai-agent.component.html',
  styles: [`.wrap{max-width:560px;margin:24px auto}`]
})
export class AiAgentComponent {
  product = '';
  status = '';
  loading = false;
  constructor(private agent: AiAgentService) {}

  buy() {
    this.status = '';
    if (!this.product.trim()) { this.status = 'Enter a product name'; return; }
    this.loading = true;
    this.agent.buyProductByName(this.product.trim()).subscribe({
      next: order => { this.loading = false; this.status = `Order ${order.id} created, redirecting...`; },
      error: err => { this.loading = false; this.status = `Error: ${err?.message || err}`; }
    });
  }
}
<div class="wrap">
  <h2>AI Purchase Agent</h2>
  <div>
    <label>Product name</label>
    <input [(ngModel)]="product" placeholder="e.g. wireless headphones" />
  </div>
  <div style="margin-top:12px">
    <button (click)="buy()" [disabled]="loading">Buy with Agent</button>
  </div>
  <div style="margin-top:12px;color:var(--muted)">{{ status }}</div>
</div>
